(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+y)*0.012+t*0.5)*8+Math.cos((x-y)*0.01-t*0.4)*6;
  const w2y = Math.cos((x-y)*0.014-t*0.45)*8+Math.sin((x+y)*0.011+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*50, 0.11, 2.1, 4.2],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*55, 0.075, 1.8, 2.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp+ph);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    aS2 += Math.sin(d*f*1.3-t*sp*0.8+ph*0.3)*0.5;
    iS2 += Math.cos(d*f*0.5+t*sp*0.4+ph)*0.5;
  }
  const act = (aS+aS2)/12, inh = (iS+iS2)/12;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const sp2x=180+Math.sin(t*0.4)*60, sp2y=100+Math.cos(t*0.5)*40;
  const d2=Math.sqrt((sx-sp2x)**2+(sy-sp2y)**2), a2=Math.atan2(sy-sp2y,sx-sp2x);
  const spiral2 = (Math.sin(d2*0.06+a2*3+t*1.8)+Math.sin(d2*0.045-a2*5+t*1.3))*0.2;
  const lap = (Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.2-t*0.7)*Math.cos(sy*0.18+t*0.5)*0.3);
  const cell = Math.tanh(lap*1.5)*0.3;
  const grain = Math.sin(sx*1.7+sy*2.3+t*4)*Math.sin(sx*2.1-sy*1.9-t*3.5)*0.04;
  const reaction = Math.tanh((act-inh*0.65+bg*0.3+spiral+spiral2)*2.0);
  const membrane = 1.0-Math.abs(Math.sin(reaction*Math.PI*1.5))*0.15;
  const pulse = 0.92+Math.sin(t*0.8)*0.08;
  const blend = reaction*0.6+cell*0.25+grain+spiral2*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,90],[12,85,120],[18,130,130],[60,165,125],
    [170,185,80],[210,170,60],[220,120,55],[190,65,55],[120,30,50],
    [60,15,45],[20,10,40],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = (0.85+Math.sin(reaction*Math.PI)*0.15)*pulse*membrane;
  const glow = Math.max(0, reaction-0.6)*2.5;
  const edge = Math.abs(reaction)>0.75?1.1:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0
  ];
}
